#!/usr/bin/env python3
"""
docker-migrate-container.py

Copy ONE container - plus the resources it needs - from a source Docker
daemon to a target Docker daemon.

What is copied
--------------
* the container image      (docker save / docker load)
* named volumes            (definition, and data unless --volumes empty)
* user defined networks    (driver, subnets, options, labels)
* the full runtime config  (ports, env, mounts, capabilities, devices,
                            healthcheck, restart policy, logging, limits...)

What is NOT copied
------------------
Everything else living in the old daemon: unrelated images, volumes,
containers, build cache, dangling layers. That is the point: seed a fresh
Docker data-root / disk without migrating /var/lib/docker.

Usage
-----
  # old daemon still reachable, new daemon already started on the new disk
  ./docker-migrate-container.py \
      --container codx-junior \
      --source unix:///var/run/docker.sock \
      --target unix:///mnt/new-docker/docker.sock \
      --volumes data

  # move to another machine
  ./docker-migrate-container.py -c codx-junior --target ssh://root@newhost

  # print the plan only
  ./docker-migrate-container.py -c codx-junior --target ssh://root@newhost --dry-run

Requires: docker CLI (client) + python3. The helper image (alpine) is only
needed on both daemons when volume data is copied.
"""

import argparse
import fnmatch
import json
import os
import shlex
import subprocess
import sys
import tempfile
import time

DEFAULT_HELPER_IMAGE = "alpine:3.20"
BUILTIN_NETWORKS = {"host", "none", "bridge"}


class DockerError(RuntimeError):
    """Raised when a docker CLI command fails."""


def log(msg=""):
    print(msg, flush=True)


def warn(msg):
    print(f"warning: {msg}", flush=True)


def fail(msg):
    print(f"error: {msg}", file=sys.stderr, flush=True)
    sys.exit(1)


def shell_join(argv):
    return " ".join(shlex.quote(str(a)) for a in argv)


class Docker:
    """Thin wrapper around the docker CLI bound to a single daemon."""

    def __init__(self, host=None, side="local"):
        self.host = host
        self.side = side

    @property
    def label(self):
        return f"{self.side} ({self.host or 'default socket'})"

    def argv(self, args):
        cmd = ["docker"]
        if self.host:
            cmd += ["-H", self.host]
        return cmd + [str(a) for a in args]

    def call(self, args, input_bytes=None):
        return subprocess.run(
            self.argv(args),
            input=input_bytes,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )

    def run(self, args, input_bytes=None, check=True):
        proc = self.call(args, input_bytes=input_bytes)
        if check and proc.returncode != 0:
            raise DockerError(
                f"[{self.side}] {shell_join(self.argv(args))}\n"
                f"{proc.stderr.decode(errors='replace').strip()}"
            )
        return proc.stdout.decode(errors="replace")

    def json(self, args):
        out = self.run(args).strip()
        return json.loads(out) if out else []

    def exists(self, kind, name):
        return self.call([kind, "inspect", name]).returncode == 0

    def popen(self, args, **kwargs):
        return subprocess.Popen(self.argv(args), **kwargs)


# ---------------------------------------------------------------------------
# Generic helpers
# ---------------------------------------------------------------------------

def parse_map(values, option):
    """Parse a list of OLD=NEW strings into a dict."""
    result = {}
    for value in values or []:
        if "=" not in value:
            fail(f"{option} expects OLD=NEW, got '{value}'")
        old, new = value.split("=", 1)
        result[old] = new
    return result


def check_daemon(dk):
    try:
        version = dk.run(["version", "--format", "{{.Server.Version}}"]).strip()
    except DockerError as ex:
        fail(f"cannot reach docker daemon {dk.label}: {ex}")
    log(f"  {dk.label}: server {version}")


def ensure_image(dk, ref):
    if dk.exists("image", ref):
        return
    log(f"  pulling {ref} on {dk.side}")
    dk.run(["pull", ref])


def confirm(prompt):
    try:
        answer = input(f"{prompt} [y/N] ").strip().lower()
    except EOFError:
        answer = "n"
    if answer not in ("y", "yes"):
        fail("aborted by user")


def map_bind_source(args, path):
    """Rewrite a bind mount source path using --mount-map OLD=NEW."""
    for old, new in args.mount_map.items():
        old = old.rstrip("/")
        if path == old:
            return new
        if path.startswith(old + "/"):
            return new.rstrip("/") + path[len(old):]
    return path


def clean_aliases(container, netcfg):
    """Network aliases without the implicit container name / short id."""
    implicit = {container["Name"].lstrip("/"), container["Id"][:12]}
    return [a for a in (netcfg.get("Aliases") or []) if a not in implicit]


# ---------------------------------------------------------------------------
# Step 1: image
# ---------------------------------------------------------------------------

def transfer_image(args, src, tgt, container):
    image_id = container["Image"]
    if not src.exists("image", image_id):
        fail(f"image {image_id} of container {container['Name']} is missing on source")

    try:
        info = src.json(["image", "inspect", image_id])[0]
    except (DockerError, IndexError):
        info = {}

    tags = [t for t in (info.get("RepoTags") or []) if t and t != "<none>:<none>"]
    image_ref = tags[0] if tags else None

    if args.image == "skip":
        ref = image_ref or image_id
        log(f"  transfer skipped, expecting {ref} on the target")
        return ref

    if not image_ref:
        image_ref = f"codx-migrate/{container['Name'].lstrip('/')}:{int(time.time())}"
        log(f"  source image is untagged, tagging it {image_ref}")
        if not args.dry_run:
            src.run(["tag", image_id, image_ref])

    if tgt.exists("image", image_ref):
        log(f"  {image_ref} already present on target")
        return image_ref

    if args.dry_run:
        log(f"  would save {image_ref} and load it into the target")
        return image_ref

    fd, tar_path = tempfile.mkstemp(prefix="docker-migrate-", suffix=".tar")
    os.close(fd)
    try:
        log(f"  saving {image_ref}")
        src.run(["save", "-o", tar_path, image_ref])
        size_mb = os.path.getsize(tar_path) / (1024 * 1024)
        log(f"  loading {size_mb:.0f} MB into target")
        tgt.run(["load", "-i", tar_path])
    finally:
        os.unlink(tar_path)

    return image_ref


# ---------------------------------------------------------------------------
# Step 2: networks
# ---------------------------------------------------------------------------

def migrate_networks(args, src, tgt, container):
    """Create the user defined networks on the target. Returns name mapping."""
    mapping = {}
    networks = (container.get("NetworkSettings") or {}).get("Networks") or {}

    for name in networks:
        target_name = args.network_map.get(name, name)
        mapping[name] = target_name

        if name in BUILTIN_NETWORKS:
            log(f"  {name} is built in, reusing it")
            continue
        if tgt.exists("network", target_name):
            log(f"  {target_name} already exists on target")
            continue

        info = src.json(["network", "inspect", name])[0]
        argv = ["network", "create", "--driver", info.get("Driver") or "bridge"]

        for conf in (info.get("IPAM") or {}).get("Config") or []:
            if conf.get("Subnet"):
                argv += ["--subnet", conf["Subnet"]]
            if conf.get("IPRange"):
                argv += ["--ip-range", conf["IPRange"]]
            if conf.get("Gateway"):
                argv += ["--gateway", conf["Gateway"]]
        if info.get("Internal"):
            argv.append("--internal")
        if info.get("Attachable"):
            argv.append("--attachable")
        if info.get("EnableIPv6"):
            argv.append("--ipv6")
        for key, value in (info.get("Options") or {}).items():
            argv += ["--opt", f"{key}={value}"]
        for key, value in (info.get("Labels") or {}).items():
            argv += ["--label", f"{key}={value}"]
        argv.append(target_name)

        log(f"  creating {target_name}")
        if args.dry_run:
            log(f"    {shell_join(tgt.argv(argv))}")
            continue
        try:
            tgt.run(argv)
        except DockerError as ex:
            warn(f"could not create network {target_name}: {ex}")
            warn("if the subnet is already in use, remap it with --network-map OLD=NEW")

    return mapping


# ---------------------------------------------------------------------------
# Step 3: volumes
# ---------------------------------------------------------------------------

def create_volume(args, src, tgt, name):
    """Create a named volume on the target. Returns True when created."""
    if tgt.exists("volume", name):
        log(f"  {name} already exists on target")
        return False

    info = src.json(["volume", "inspect", name])[0]
    driver = info.get("Driver") or "local"
    options = info.get("Options") or {}

    argv = ["volume", "create", "--name", name]
    if driver != "local":
        argv += ["--driver", driver]
    elif "device" in options:
        warn(
            f"volume {name} is a bind backed local volume "
            f"(device={options.get('device')}): that path must exist on the target host"
        )
    for key, value in options.items():
        if value is not None:
            argv += ["--opt", f"{key}={value}"]
    for key, value in (info.get("Labels") or {}).items():
        argv += ["--label", f"{key}={value}"]

    log(f"  creating {name}")
    if args.dry_run:
        log(f"    {shell_join(tgt.argv(argv))}")
        return True
    tgt.run(argv)
    return True


def copy_volume_data(args, src, tgt, name):
    """Stream the content of a volume from source to target via tar."""
    read_cmd = ["run", "--rm", "-v", f"{name}:/from:ro",
                args.helper_image, "tar", "cf", "-", "-C", "/from", "."]
    write_cmd = ["run", "--rm", "-i", "-v", f"{name}:/to",
                 args.helper_image, "tar", "xf", "-", "-C", "/to"]

    log(f"  copying data of {name}")
    if args.dry_run:
        log(f"    {shell_join(src.argv(read_cmd))} | {shell_join(tgt.argv(write_cmd))}")
        return

    ensure_image(src, args.helper_image)
    ensure_image(tgt, args.helper_image)

    with tempfile.TemporaryFile() as src_err, tempfile.TemporaryFile() as tgt_err:
        reader = src.popen(read_cmd, stdout=subprocess.PIPE, stderr=src_err)
        writer = tgt.popen(write_cmd, stdin=reader.stdout,
                           stdout=subprocess.DEVNULL, stderr=tgt_err)
        reader.stdout.close()
        writer.wait()
        reader.wait()

        if reader.returncode != 0:
            src_err.seek(0)
            raise DockerError(
                f"reading volume {name} failed: {src_err.read().decode(errors='replace')}"
            )
        if writer.returncode != 0:
            tgt_err.seek(0)
            raise DockerError(
                f"writing volume {name} failed: {tgt_err.read().decode(errors='replace')}"
            )


def migrate_volumes(args, src, tgt, container):
    seen = set()
    for mount in container.get("Mounts") or []:
        if mount.get("Type") != "volume":
            continue
        name = mount.get("Name")
        if not name or name in seen:
            continue
        seen.add(name)

        if any(fnmatch.fnmatch(name, pat) for pat in args.volume_exclude):
            log(f"  {name} excluded, left to docker defaults")
            continue

        created = create_volume(args, src, tgt, name)
        if args.volumes == "data":
            copy_volume_data(args, src, tgt, name)
        elif created:
            log(f"  {name} created empty (data not copied)")


# ---------------------------------------------------------------------------
# Step 4: container
# ---------------------------------------------------------------------------

def build_run_args(args, container, image_ref, network_map):
    """Translate `docker inspect` into a `docker run` argv list."""
    cfg = container.get("Config") or {}
    host = container.get("HostConfig") or {}
    name = args.new_name or container["Name"].lstrip("/")
    argv = ["run", "-d", "--name", name]

    # entrypoint / command (docker run has a single --entrypoint value)
    entrypoint = cfg.get("Entrypoint") or []
    command = cfg.get("Cmd") or []
    if isinstance(entrypoint, str):
        entrypoint = shlex.split(entrypoint)
    if isinstance(command, str):
        command = shlex.split(command)
    if entrypoint:
        argv += ["--entrypoint", entrypoint[0]]
        command = list(entrypoint[1:]) + list(command)

    if cfg.get("User"):
        argv += ["--user", cfg["User"]]
    if cfg.get("WorkingDir"):
        argv += ["--workdir", cfg["WorkingDir"]]
    hostname = cfg.get("Hostname")
    if hostname and hostname != container["Id"][:12]:
        argv += ["--hostname", hostname]
    for env in cfg.get("Env") or []:
        argv += ["--env", env]
    for key, value in (cfg.get("Labels") or {}).items():
        if any(key.startswith(prefix) for prefix in args.drop_label_prefix):
            continue
        argv += ["--label", f"{key}={value}"]

    healthcheck = cfg.get("Healthcheck") or {}
    test = healthcheck.get("Test") or []
    if test:
        if test[0] == "CMD":
            argv += ["--health-cmd", " ".join(shlex.quote(t) for t in test[1:])]
        elif test[0] == "CMD-SHELL":
            argv += ["--health-cmd", test[1]]
        elif test[0] == "NONE":
            argv.append("--no-healthcheck")
        if healthcheck.get("Interval"):
            argv += ["--health-interval", str(healthcheck["Interval"])]
        if healthcheck.get("Timeout"):
            argv += ["--health-timeout", str(healthcheck["Timeout"])]
        if healthcheck.get("Retries"):
            argv += ["--health-retries", str(healthcheck["Retries"])]
        if healthcheck.get("StartPeriod"):
            argv += ["--health-start-period", str(healthcheck["StartPeriod"])]
    if cfg.get("StopSignal"):
        argv += ["--stop-signal", cfg["StopSignal"]]
    if host.get("StopTimeout"):
        argv += ["--stop-timeout", str(host["StopTimeout"])]

    # networking
    network_mode = host.get("NetworkMode") or "default"
    networks = (container.get("NetworkSettings") or {}).get("Networks") or {}
    extra_networks = []
    host_network = network_mode == "host"

    if network_mode in ("host", "none") or network_mode.startswith("container:"):
        argv += ["--network", network_mode]
    elif networks:
        items = list(networks.items())
        primary_name, primary_cfg = items[0]
        argv += ["--network", network_map.get(primary_name, primary_name)]
        for alias in clean_aliases(container, primary_cfg):
            argv += ["--network-alias", alias]
        static_ip = (primary_cfg.get("IPAMConfig") or {}).get("IPv4Address")
        if args.keep_static_ip and static_ip:
            argv += ["--ip", static_ip]
        for net_name, net_cfg in items[1:]:
            extra_networks.append((
                network_map.get(net_name, net_name),
                clean_aliases(container, net_cfg),
                (net_cfg.get("IPAMConfig") or {}).get("IPv4Address"),
            ))

    if not host_network:
        for container_port, bindings in (host.get("PortBindings") or {}).items():
            for binding in bindings or [{}]:
                host_ip = binding.get("HostIp") or ""
                host_port = binding.get("HostPort") or ""
                if host_ip or host_port:
                    argv += ["--publish", f"{host_ip}:{host_port}:{container_port}"]
                else:
                    argv += ["--publish", container_port]

    # tmpfs are not listed in "Mounts", they live in HostConfig
    for destination, options in (host.get("Tmpfs") or {}).items():
        argv += ["--tmpfs", f"{destination}:{options}" if options else destination]

    # volumes and bind mounts
    for mount in container.get("Mounts") or []:
        mtype = mount.get("Type")
        destination = mount.get("Destination")
        if mtype == "tmpfs":
            continue
        if mtype == "volume":
            spec = f"{mount['Name']}:{destination}"
        elif mtype == "bind":
            source = map_bind_source(args, mount["Source"])
            if source != mount["Source"]:
                log(f"  remapping bind {mount['Source']} -> {source}")
            spec = f"{source}:{destination}"
        else:
            warn(f"skipping unsupported mount type {mtype} at {destination}")
            continue
        options = []
        if not mount.get("RW", True):
            options.append("ro")
        if mount.get("Propagation"):
            options.append(mount["Propagation"])
        if options:
            spec += ":" + ",".join(options)
        argv += ["--volume", spec]

    # security and runtime
    for cap in host.get("CapAdd") or []:
        argv += ["--cap-add", cap]
    for cap in host.get("CapDrop") or []:
        argv += ["--cap-drop", cap]
    for option in host.get("SecurityOpt") or []:
        argv += ["--security-opt", option]
    for device in host.get("Devices") or []:
        spec = device.get("PathOnHost")
        if device.get("PathInContainer") and device["PathInContainer"] != spec:
            spec += f":{device['PathInContainer']}"
        if device.get("CgroupPermissions"):
            spec += f":{device['CgroupPermissions']}"
        argv += ["--device", spec]
    if host.get("Privileged"):
        argv.append("--privileged")
    for key, value in (host.get("Sysctls") or {}).items():
        argv += ["--sysctl", f"{key}={value}"]
    for group in host.get("GroupAdd") or []:
        argv += ["--group-add", group]
    for ulimit in host.get("Ulimits") or []:
        spec = ulimit.get("Name")
        if ulimit.get("Soft"):
            spec += f"={ulimit['Soft']}:{ulimit.get('Hard', ulimit['Soft'])}"
        argv += ["--ulimit", spec]
    if host.get("ReadonlyRootfs"):
        argv.append("--read-only")
    if host.get("Init"):
        argv.append("--init")
    if host.get("IpcMode") and host["IpcMode"] not in ("private", ""):
        argv += ["--ipc", host["IpcMode"]]
    if host.get("PidMode"):
        argv += ["--pid", host["PidMode"]]
    if host.get("UTSMode"):
        argv += ["--uts", host["UTSMode"]]
    if host.get("UsernsMode"):
        argv += ["--userns", host["UsernsMode"]]
    if host.get("CgroupnsMode") and host["CgroupnsMode"] not in ("private", ""):
        argv += ["--cgroupns", host["CgroupnsMode"]]
    if host.get("Runtime") and host["Runtime"] != "runc":
        argv += ["--runtime", host["Runtime"]]

    # resources
    if host.get("ShmSize"):
        argv += ["--shm-size", str(host["ShmSize"])]
    if host.get("Memory"):
        argv += ["--memory", str(host["Memory"])]
    if host.get("MemorySwap"):
        argv += ["--memory-swap", str(host["MemorySwap"])]
    if host.get("NanoCpus"):
        argv += ["--cpus", f"{host['NanoCpus'] / 1e9:g}"]
    if host.get("CpuShares"):
        argv += ["--cpu-shares", str(host["CpuShares"])]
    if host.get("CpuQuota"):
        argv += ["--cpu-quota", str(host["CpuQuota"])]
    if host.get("CpuPeriod"):
        argv += ["--cpu-period", str(host["CpuPeriod"])]
    if host.get("CpusetCpus"):
        argv += ["--cpuset-cpus", host["CpusetCpus"]]
    if host.get("CpusetMems"):
        argv += ["--cpuset-mems", host["CpusetMems"]]
    if host.get("PidsLimit"):
        argv += ["--pids-limit", str(host["PidsLimit"])]

    for dns in host.get("Dns") or []:
        argv += ["--dns", dns]
    for search in host.get("DnsSearch") or []:
        argv += ["--dns-search", search]
    for extra_host in host.get("ExtraHosts") or []:
        argv += ["--add-host", extra_host]

    restart = host.get("RestartPolicy") or {}
    if restart.get("Name") and restart["Name"] != "no":
        policy = restart["Name"]
        if policy == "on-failure" and restart.get("MaximumRetryCount"):
            policy += f":{restart['MaximumRetryCount']}"
        argv += ["--restart", policy]

    log_config = host.get("LogConfig") or {}
    log_type = log_config.get("Type") or "json-file"
    log_opts = log_config.get("Config") or {}
    if log_type != "json-file" or log_opts:
        argv += ["--log-driver", log_type]
        for key, value in log_opts.items():
            argv += ["--log-opt", f"{key}={value}"]

    argv.append(image_ref)
    argv += [str(c) for c in command]
    return argv, extra_networks


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def parse_args():
    parser = argparse.ArgumentParser(
        description="Copy one container with its image, volumes and networks "
                    "from a source Docker daemon to a target Docker daemon.",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    parser.add_argument("-c", "--container", required=True,
                        help="name or id of the container to migrate")
    parser.add_argument("--source", default=None,
                        help="source docker endpoint (unix://, tcp://, ssh://); "
                             "defaults to the local socket")
    parser.add_argument("--target", default=None,
                        help="target docker endpoint (unix://, tcp://, ssh://); "
                             "defaults to the local socket")
    parser.add_argument("--new-name", default=None,
                        help="name of the container on the target "
                             "(default: same name)")
    parser.add_argument("--volumes", choices=["data", "empty"], default="data",
                        help="copy volume data or create empty volumes (default: data)")
    parser.add_argument("--volume-exclude", action="append", default=[],
                        metavar="PATTERN",
                        help="glob of volume names to leave empty (repeatable)")
    parser.add_argument("--mount-map", action="append", default=[],
                        metavar="OLD=NEW",
                        help="rewrite bind mount sources, e.g. /mnt/old=/mnt/new")
    parser.add_argument("--network-map", action="append", default=[],
                        metavar="OLD=NEW",
                        help="attach to an existing target network instead of "
