    parser.add_argument("--yes", action="store_true",
                        help="do not ask for confirmation")
    return parser.parse_args()


def main():
    args = parse_args()
    args.mount_map = parse_map(args.mount_map, "--mount-map")
    args.network_map = parse_map(args.network_map, "--network-map")

    src = Docker(args.source, "source")
    tgt = Docker(args.target, "target")
    if args.source == args.target:
        warn("source and target point to the same daemon")

    log("Checking daemons")
    check_daemon(src)
    check_daemon(tgt)

    log(f"Reading container {args.container}")
    try:
        container = src.json(["container", "inspect", args.container])[0]
    except (DockerError, IndexError) as ex:
        fail(f"container {args.container} not found on source: {ex}")

    name = args.new_name or container["Name"].lstrip("/")
    log("")
    log(f"Container : {container['Name'].lstrip('/')}")
    log(f"Image     : {(container.get('Config') or {}).get('Image')}")
    log(f"Target    : {tgt.label} as '{name}'")
    log(f"Volumes   : {args.volumes}")
    if args.dry_run:
        log("(dry run: nothing will be changed)")
    elif not args.yes:
        confirm("Proceed with the migration?")

    log("")
    log("Image")
    image_ref = transfer_image(args, src, tgt, container)

    log("")
    log("Networks")
    network_map = migrate_networks(args, src, tgt, container)

    log("")
    log("Volumes")
    migrate_volumes(args, src, tgt, container)

    log("")
    log("Container")
    if tgt.exists("container", name):
        if not args.replace:
