        log(f"  removing existing container {name}")
        if not args.dry_run:
            tgt.run(["rm", "-f", name])

    argv, extra_networks = build_run_args(args, container, image_ref, network_map)
    log(f"  {shell_join(tgt.argv(argv))}")

    if not args.dry_run:
