            connect += [net_name, name]
            log(f"  {shell_join(tgt.argv(connect))}")
            tgt.run(connect)

    log("")
    if args.dry_run:
        log("Dry run finished, nothing was changed.")
        return

    log(f"Done. Container '{name}' is running on {tgt.label}")
    log(f"Follow its logs with: docker{' -H ' + args.target if args.target else ''} logs -f {name}")


